sp_widget.client_script:
api.controller = function() {
  var c = this;
  c.submitting = false;
  c.errorMsg = '';
  c.form = {
    type: '',
    severity: '',
    location: '',
    short_description: '',
    description: ''
  };

  c.triggerUpload = function() {
    alert('Drag and drop files to attach. Max size: 10 MB per file.');
  };

  c.submitForm = function() {
    c.errorMsg = '';
    if (!c.form.type || !c.form.severity || !c.form.location || !c.form.short_description) {
      c.errorMsg = 'Please fill out all required fields marked with *.';
      return;
    }
    c.submitting = true;
    c.data.action = 'create';
    c.data.form = c.form;

    c.server.update().then(function() {
      c.submitting = false;
      if (c.data.result && c.data.result.success) {
        // Redirect to Screen 7 (Exception Submitted)
        window.location.href = '?id=exception_submitted&sys_id=' + c.data.result.sys_id;
      } else {
        c.errorMsg = (c.data.result && c.data.result.message) || 'Error submitting exception.';
      }
    });
  };
};

sp_widget.css:
.wei-report-wrapper {
  max-width: 640px;
  margin: 30px auto 50px;
  padding: 0 16px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.wei-report-card {
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 8px;
  padding: 32px 36px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}
.wei-report-header {
  margin-bottom: 24px;
}
.wei-report-title {
  font-size: 22px;
  font-weight: 700;
  color: #0F172A;
  margin: 0 0 4px;
}
.wei-report-subtitle {
  font-size: 13px;
  color: #64748B;
  margin: 0;
}
.wei-label {
  font-size: 13px;
  font-weight: 600;
  color: #334155;
  margin-bottom: 6px;
}
.wei-select, .wei-input, .wei-textarea {
  border: 1px solid #CBD5E1 !important;
  border-radius: 6px !important;
  font-size: 13px !important;
  color: #1E293B !important;
}
.wei-select:focus, .wei-input:focus, .wei-textarea:focus {
  border-color: #1976D2 !important;
  box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.15) !important;
}
.wei-dropzone {
  border: 1.5px dashed #CBD5E1;
  border-radius: 6px;
  background: #F8FAFC;
  padding: 24px 16px;
  text-align: center;
  cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}
.wei-dropzone:hover {
  border-color: #1976D2;
  background: #F0F7FF;
}
.dropzone-icon {
  font-size: 18px;
  color: #64748B;
}
.dropzone-text {
  font-size: 12px;
  color: #64748B;
}
.wei-form-buttons {
  display: flex;
  gap: 12px;
  margin-top: 24px;
}
.btn-submit-report {
  background: #1976D2;
  border-color: #1976D2;
  font-size: 13px;
  font-weight: 600;
  padding: 8px 24px;
  border-radius: 6px;
}
.btn-submit-report:hover { background: #1565C0; }
.btn-cancel-report {
  font-size: 13px;
  font-weight: 500;
  padding: 8px 20px;
  border-radius: 6px;
  border: 1px solid #CBD5E1;
  color: #475569;
}

sp_widget.script:
(function() {
  var isStaff = gs.hasRole('x_1956908_wareho_0.staff');
  var isTech = gs.hasRole('x_1956908_wareho_0.technician');
  var isSup = gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin');

  data.allowed = isStaff || isTech || isSup;
  if (!data.allowed) {
    data.error = 'Access denied';
    return;
  }

  var tableName = 'x_1956908_wareho_0_exception';

  if (input && input.action === 'create' && input.form) {
    var form = input.form;
    var gr = new GlideRecord(tableName);
    gr.initialize();
    gr.setValue('exception_type', form.type);
    gr.setValue('severity', form.severity);
    gr.setValue('location', form.location);
    gr.setValue('short_description', form.short_description);
    gr.setValue('description', form.description || '');
    gr.setValue('status', 'new');
    gr.setValue('reported_by', gs.getUserID());

    var newId = gr.insert();
    if (newId) {
      data.result = {
        success: true,
        sys_id: newId + ''
      };
    } else {
      data.result = {
        success: false,
        message: 'Database insert failed. Check ACL permissions.'
      };
    }
  }
})();
